// Checks that strict-settings.json equals the project settings generated by the framework.
// Run with: node --test testbench/runners/lib/sync-strict-settings.test.mjs

import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { projectSettingsText } from '../../../yllir/scripts/lib/instructions.mjs';
import { STRICT_SETTINGS_PATH, strictSettingsInSync } from './sync-strict-settings.mjs';

test('strict-settings.json is byte-equal to the generated project settings', () => {
  assert.equal(fs.readFileSync(STRICT_SETTINGS_PATH, 'utf8'), projectSettingsText());
  assert.equal(strictSettingsInSync(), true);
});

test('strict-settings.json allows the skills scripts, not only the engine', () => {
  const allow = JSON.parse(fs.readFileSync(STRICT_SETTINGS_PATH, 'utf8')).permissions.allow;
  assert.ok(allow.includes('Bash(node "*/skills/library/update/scripts/item-descriptions.mjs" *)'));
  assert.ok(allow.includes('Bash(node "*/scripts/engine.mjs" *)'));
});
